using System;using System.IO;using System.Linq;using System.Text;using System.Threading;
namespace TavernLens {public static class MidgameTests {
 public static int Run(string log){string path=Path.Combine(Path.GetTempPath(),"tavern-midgame-"+Guid.NewGuid()+".log");int checks=0;Action<bool,string> check=(ok,msg)=>{if(!ok)throw new Exception("Midgame test: "+msg);checks++;};try{var expected=new MatchState{Stream=path};using(var output=new StreamWriter(path,false,new UTF8Encoding(false))){output.WriteLine("D 00:00:00 PowerTaskList.DebugPrintPower() - CREATE_GAME");output.WriteLine("D 00:00:00 PowerTaskList.DebugPrintPower() - TAG_CHANGE Entity=GameEntity tag=STATE value=COMPLETE");foreach(var line in File.ReadLines(log)){output.WriteLine(line);expected.Feed(line);if(expected.Turn>=8&&expected.Phase=="Recruit")break;}}check(expected.LastFights.Count>0,"fixture contains previous opponents");var start=LiveReader.Locate(path,CancellationToken.None);check(start.Start>0&&!start.Complete,"skips completed earlier match");using(var reader=new LiveReader(path)){for(int i=0;i<2000&&!reader.CaughtUp&&reader.Error=="";i++)Thread.Sleep(10);check(reader.Error==""&&reader.CaughtUp,"background recovery finishes");check(reader.Latest.Turn==expected.Turn&&reader.Latest.Solo,"joins correct active turn");check(reader.Latest.LastFights.Count==expected.LastFights.Count,"restores enemy board history");foreach(var pair in expected.LastFights){var actual=reader.Latest.LastFights[pair.Key];check(String.Join("|",actual.Enemy.Select(e=>e.CardId+":"+e.N("ATK")+":"+e.N("ZONE_POSITION")))==String.Join("|",pair.Value.Enemy.Select(e=>e.CardId+":"+e.N("ATK")+":"+e.N("ZONE_POSITION"))),"restores identity stats and layout");}check(reader.Drain().Length==0,"does not replay old results");File.AppendAllText(path,"D 12:00:00 PowerTaskList.DebugPrintPower() - TAG_CHANGE Entity=GameEntity tag=TURN value=19\n");for(int i=0;i<200&&reader.Latest.Turn!=10;i++)Thread.Sleep(10);check(reader.Latest.Turn==10,"live events continue after replay");}File.AppendAllText(path,"D 12:00:00 PowerTaskList.DebugPrintPower() - TAG_CHANGE Entity=GameEntity tag=STATE value=COMPLETE\n");using(var reader=new LiveReader(path)){for(int i=0;i<500&&!reader.CaughtUp&&reader.Error=="";i++)Thread.Sleep(10);check(reader.CaughtUp&&!reader.Latest.Started&&reader.Latest.LastFights.Count==0&&reader.Drain().Length==0,"finished match stays unloaded at next boot");}}finally{File.Delete(path);}return checks;}
}}
